-- SELECT 'Admissions' AS metric, COUNT(DISTINCT admission_id) AS value, 'Distinct admissions (admission_id)' AS notes FROM admissions UNION ALL SELECT 'Avg LOS (days)', ROUND(AVG(JULIANDAY(discharge_dt) - JULIANDAY(admit_dt)), 1), 'Excludes active (null discharge_dt)' FROM admissions WHERE discharge_dt IS NOT NULL AND discharge_dt <> '' AND JULIANDAY(discharge_dt) >= JULIANDAY(admit_dt) UNION ALL SELECT 'LWBS %', ROUND( (SUM(CASE WHEN LOWER(TRIM(dispo)) = 'lwbs' THEN 1 ELSE 0 END) * 100.0) / NULLIF(COUNT(*), 0) , 1), 'ed_visits.dispo = LWBS' FROM ed_visits UNION ALL SELECT 'Avg Door-to-Doc (min)', CAST(ROUND(AVG(door_to_doc_min * 1.0), 0) AS INTEGER), 'Mean of ed_visits.door_to_doc_min (>=0)' FROM ed_visits WHERE door_to_doc_min IS NOT NULL AND door_to_doc_min >= 0 ;
-- SELECT 'Admissions' AS metric, COUNT(DISTINCT admission_id) AS value, 'Distinct admissions (last 90d)' AS notes FROM admissions WHERE DATE(admit_dt) >= DATE('now','-90 day') UNION ALL SELECT 'Avg LOS (days)', ROUND(AVG(JULIANDAY(discharge_dt) - JULIANDAY(admit_dt)), 1), 'Excludes active; admits last 90d' FROM admissions WHERE discharge_dt IS NOT NULL AND discharge_dt <> '' AND JULIANDAY(discharge_dt) >= JULIANDAY(admit_dt) AND DATE(admit_dt) >= DATE('now','-90 day') UNION ALL SELECT 'LWBS %', ROUND( (SUM(CASE WHEN LOWER(TRIM(dispo)) = 'lwbs' THEN 1 ELSE 0 END) * 100.0) / NULLIF(COUNT(*), 0) , 1), 'ed_visits.dispo = LWBS; last 90d' FROM ed_visits WHERE DATE(arrival_ts) >= DATE('now','-90 day') UNION ALL SELECT 'Avg Door-to-Doc (min)', CAST(ROUND(AVG(door_to_doc_min * 1.0), 0) AS INTEGER), 'Mean DTD (>=0); last 90d' FROM ed_visits WHERE door_to_doc_min IS NOT NULL AND door_to_doc_min >= 0 AND DATE(arrival_ts) >= DATE('now','-90 day') ;